using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        #region Constructor Tests

        [Fact]
        public void Constructor_ValidInputs_SetsPageIndexAndItems()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };
            int count = 10;
            int pageIndex = 2;
            int pageSize = 3;

            // Act
            var result = new PaginatedList<string>(items, count, pageIndex, pageSize);

            // Assert
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(4, result.TotalPages); // ceil(10/3) = 4
            Assert.Equal(3, result.Count);
            Assert.Equal("a", result[0]);
            Assert.Equal("b", result[1]);
            Assert.Equal("c", result[2]);
        }

        [Fact]
        public void Constructor_CountRequiresCeiling_RoundsTotalPagesUp()
        {
            // Arrange & Act
            var result = new PaginatedList<int>(new List<int> { 1 }, count: 7, pageIndex: 1, pageSize: 3);

            // Assert — ceil(7/3) = 3
            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void Constructor_EmptyItems_CreatesEmptyList()
        {
            // Arrange & Act
            var result = new PaginatedList<int>(new List<int>(), count: 0, pageIndex: 1, pageSize: 5);

            // Assert
            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
            Assert.Equal(1, result.PageIndex);
        }

        [Fact]
        public void Constructor_SinglePage_TotalPagesIsOne()
        {
            // Arrange & Act
            var result = new PaginatedList<int>(new List<int> { 1, 2, 3 }, count: 3, pageIndex: 1, pageSize: 5);

            // Assert — ceil(3/5) = 1
            Assert.Equal(1, result.TotalPages);
        }

        #endregion

        #region HasPreviousPage Tests

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            var result = new PaginatedList<int>(new List<int> { 1 }, count: 10, pageIndex: 1, pageSize: 5);
            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            var result = new PaginatedList<int>(new List<int> { 1 }, count: 10, pageIndex: 2, pageSize: 5);
            Assert.True(result.HasPreviousPage);
        }

        #endregion

        #region HasNextPage Tests

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            // count=10, pageSize=5 → TotalPages=2, pageIndex=2 → no next page
            var result = new PaginatedList<int>(new List<int> { 1 }, count: 10, pageIndex: 2, pageSize: 5);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_NotLastPage_ReturnsTrue()
        {
            // count=10, pageSize=5 → TotalPages=2, pageIndex=1 → has next page
            var result = new PaginatedList<int>(new List<int> { 1 }, count: 10, pageIndex: 1, pageSize: 5);
            Assert.True(result.HasNextPage);
        }

        #endregion

        #region Create (static factory) Tests

        [Fact]
        public void Create_FirstPage_ReturnsCorrectItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 15).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 5);

            // Assert
            Assert.Equal(5, result.Count);
            Assert.Equal(new[] { 1, 2, 3, 4, 5 }, result.ToArray());
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages); // ceil(15/5) = 3
        }

        [Fact]
        public void Create_MiddlePage_SkipsAndTakes()
        {
            // Arrange
            var source = Enumerable.Range(1, 15).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 5);

            // Assert
            Assert.Equal(5, result.Count);
            Assert.Equal(new[] { 6, 7, 8, 9, 10 }, result.ToArray());
            Assert.Equal(2, result.PageIndex);
        }

        [Fact]
        public void Create_LastPartialPage_ReturnsRemainingItems()
        {
            // Arrange — 12 items, pageSize=5, page 3 → items 11, 12
            var source = Enumerable.Range(1, 12).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 5);

            // Assert
            Assert.Equal(2, result.Count);
            Assert.Equal(new[] { 11, 12 }, result.ToArray());
            Assert.Equal(3, result.TotalPages); // ceil(12/5) = 3
            Assert.False(result.HasNextPage);
            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            // Arrange
            var source = Enumerable.Empty<string>().AsQueryable();

            // Act
            var result = PaginatedList<string>.Create(source, pageIndex: 1, pageSize: 10);

            // Assert
            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_PageSizeLargerThanSource_ReturnsAllItems()
        {
            // Arrange
            var source = new List<string> { "x", "y", "z" }.AsQueryable();

            // Act
            var result = PaginatedList<string>.Create(source, pageIndex: 1, pageSize: 10);

            // Assert
            Assert.Equal(3, result.Count);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasNextPage);
            Assert.False(result.HasPreviousPage);
            Assert.Equal("x", result[0]);
            Assert.Equal("z", result[2]);
        }

        [Theory]
        [InlineData(1, 3, 5, 1)]  // 1 item, page size 3 → 1 total page, page 1 has 1 item
        [InlineData(10, 3, 4, 1)]  // 10 items, page size 3 → 4 total pages, page 1 has 3 items
        [InlineData(10, 10, 1, 10)] // 10 items, page size 10 → 1 page, page 1 has 10 items
        [InlineData(6, 4, 2, 4)]   // 6 items, page size 4 → 2 total pages, page 1 has 4 items
        public void Create_VariousPageSizes_CalculatesTotalPagesCorrectly(
            int sourceCount, int pageSize, int expectedTotalPages, int expectedItemsOnPage1)
        {
            // Arrange
            var source = Enumerable.Range(1, sourceCount).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: pageSize);

            // Assert
            Assert.Equal(expectedTotalPages, result.TotalPages);
            Assert.Equal(expectedItemsOnPage1, result.Count);
        }

        #endregion
    }
}

using System;
using System.Collections.Generic;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain the static queue to prevent cross-test pollution
            DrainQueue();
        }

        public void Dispose()
        {
            // Drain again after each test
            DrainQueue();
            _sut.Dispose();
        }

        private void DrainQueue()
        {
            var service = new NotificationService();
            while (service.ReceiveNotification() != null) { }
        }

        #region SendNotification (4-param overload) Tests

        [Fact]
        public void SendNotification_4Params_EnqueuesNotification()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "42", EntityOperation.CREATE, "admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("admin", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            // Arrange & Act
            _sut.SendNotification("Course", "10", EntityOperation.UPDATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        #endregion

        #region SendNotification (5-param overload) Tests

        [Fact]
        public void SendNotification_WithDisplayName_SetsMessageWithName()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("Student", notification.Message);
        }

        [Fact]
        public void SendNotification_WithUserName_SetsCreatedBy()
        {
            // Arrange & Act
            _sut.SendNotification("Department", "5", "Math", EntityOperation.UPDATE, "jsmith");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("jsmith", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsIsReadFalse()
        {
            // Arrange & Act
            _sut.SendNotification("Course", "3", EntityOperation.DELETE, "user1");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToRecentTime()
        {
            // Arrange
            var before = DateTime.Now.AddSeconds(-2);

            // Act
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.True(notification.CreatedAt >= before, "CreatedAt should be >= test start time");
            Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(2), "CreatedAt should be <= now + 2s");
        }

        #endregion

        #region ReceiveNotification Tests

        [Fact]
        public void ReceiveNotification_QueueHasItems_ReturnsNotification()
        {
            // Arrange
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);

            // Act
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            // Queue is drained in constructor — should be empty
            var notification = _sut.ReceiveNotification();
            Assert.Null(notification);
        }

        [Fact]
        public void ReceiveNotification_DequeuedInFIFOOrder()
        {
            // Arrange
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);
            _sut.SendNotification("Course", "2", EntityOperation.UPDATE);
            _sut.SendNotification("Department", "3", EntityOperation.DELETE);

            // Act & Assert — FIFO order
            var first = _sut.ReceiveNotification();
            Assert.Equal("Student", first!.EntityType);
            Assert.Equal("1", first.EntityId);

            var second = _sut.ReceiveNotification();
            Assert.Equal("Course", second!.EntityType);
            Assert.Equal("2", second.EntityId);

            var third = _sut.ReceiveNotification();
            Assert.Equal("Department", third!.EntityType);
            Assert.Equal("3", third.EntityId);

            // Queue should now be empty
            Assert.Null(_sut.ReceiveNotification());
        }

        #endregion

        #region GenerateMessage (tested indirectly) Tests

        [Fact]
        public void SendNotification_CreateOperation_MessageContainsCreated()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "1", "Alice", EntityOperation.CREATE);
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Contains("has been created", notification.Message);
            Assert.StartsWith("New ", notification.Message);
        }

        [Fact]
        public void SendNotification_UpdateOperation_MessageContainsUpdated()
        {
            // Arrange & Act
            _sut.SendNotification("Course", "2", "Chemistry", EntityOperation.UPDATE);
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Contains("has been updated", notification.Message);
            Assert.DoesNotContain("New ", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_MessageContainsDeleted()
        {
            // Arrange & Act
            _sut.SendNotification("Department", "3", "Physics", EntityOperation.DELETE);
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Contains("has been deleted", notification.Message);
            Assert.DoesNotContain("New ", notification.Message);
        }

        [Fact]
        public void SendNotification_WithDisplayName_MessageUsesDisplayName()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE);
            var notification = _sut.ReceiveNotification();

            // Assert — message should use Student 'John Doe' format
            Assert.NotNull(notification);
            Assert.Contains("'John Doe'", notification.Message);
            Assert.DoesNotContain("(ID:", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_MessageUsesIdFormat()
        {
            // Arrange & Act — 4-param overload passes null for entityDisplayName
            _sut.SendNotification("Student", "42", EntityOperation.UPDATE);
            var notification = _sut.ReceiveNotification();

            // Assert — message should use Student (ID: 42) format
            Assert.NotNull(notification);
            Assert.Contains("(ID: 42)", notification.Message);
            Assert.DoesNotContain("'", notification.Message);
        }

        [Fact]
        public void SendNotification_CreateWithDisplayName_ExactMessageFormat()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "1", "Alice Smith", EntityOperation.CREATE);
            var notification = _sut.ReceiveNotification();

            // Assert — exact format: "New Student 'Alice Smith' has been created"
            Assert.NotNull(notification);
            Assert.Equal("New Student 'Alice Smith' has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_UpdateWithoutDisplayName_ExactMessageFormat()
        {
            // Arrange & Act
            _sut.SendNotification("Course", "7", EntityOperation.UPDATE);
            var notification = _sut.ReceiveNotification();

            // Assert — exact format: "Course (ID: 7) has been updated"
            Assert.NotNull(notification);
            Assert.Equal("Course (ID: 7) has been updated", notification.Message);
        }

        #endregion

        #region Queue Cap Enforcement Tests

        [Fact]
        public void SendNotification_ExceedsMaxCapacity_TrimsOldEntries()
        {
            // Arrange — send 505 notifications to exceed 500 cap
            for (int i = 0; i < 505; i++)
            {
                _sut.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
            }

            // Act — drain and count
            int count = 0;
            while (_sut.ReceiveNotification() != null)
            {
                count++;
            }

            // Assert — should be capped at 500
            Assert.True(count <= 500, $"Queue count ({count}) should be <= 500 after cap enforcement");
        }

        #endregion

        #region MarkAsRead and Dispose Tests

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // Act & Assert — no-op, should not throw
            var exception = Record.Exception(() => _sut.MarkAsRead(999));
            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            // Act & Assert — no-op, should not throw
            var exception = Record.Exception(() => _sut.Dispose());
            Assert.Null(exception);
        }

        #endregion
    }
