using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests
    {
        private static void SeedStudents(SchoolContext context)
        {
            context.Students.AddRange(
                new Student { LastName = "Adams", FirstMidName = "Alice", EnrollmentDate = new DateTime(2023, 9, 1) },
                new Student { LastName = "Baker", FirstMidName = "Bob", EnrollmentDate = new DateTime(2024, 1, 15) },
                new Student { LastName = "Clark", FirstMidName = "Cathy", EnrollmentDate = new DateTime(2023, 6, 1) }
            );
            context.SaveChanges();
        }

        #region Index Tests

        [Fact]
        public void Index_ReturnsViewWithStudents()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            SeedStudents(context);
            var controller = new StudentsController(context);

            // Act
            var result = controller.Index(null, null, null, null);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal(3, model.Count);
        }

        [Fact]
        public void Index_FiltersStudentsBySearchString_LastName()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            SeedStudents(context);
            var controller = new StudentsController(context);

            // Act — search for "Adams" (LastName match)
            var result = controller.Index(null, null, "Adams", null);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Single(model);
            Assert.Equal("Adams", model[0].LastName);
        }

        [Fact]
        public void Index_FiltersStudentsBySearchString_FirstName()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            SeedStudents(context);
            var controller = new StudentsController(context);

            // Act — search for "Bob" (FirstMidName match)
            var result = controller.Index(null, null, "Bob", null);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Single(model);
            Assert.Equal("Baker", model[0].LastName);
        }

        [Fact]
        public void Index_SearchStringNoMatch_ReturnsEmpty()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            SeedStudents(context);
            var controller = new StudentsController(context);

            // Act
            var result = controller.Index(null, null, "ZZZnonexistent", null);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Empty(model);
        }

        [Fact]
        public void Index_DefaultSort_OrdersByLastNameAscending()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            SeedStudents(context); // Adams, Baker, Clark
            var controller = new StudentsController(context);

            // Act — no sortOrder → default (OrderBy LastName asc)
            var result = controller.Index(null, null, null, null);

            // Assert
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(
                Assert.IsType<ViewResult>(result).Model);
            Assert.Equal("Adams", model[0].LastName);
            Assert.Equal("Baker", model[1].LastName);
            Assert.Equal("Clark", model[2].LastName);
        }

        [Fact]
        public void Index_SortsByNameDescending()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            SeedStudents(context);
            var controller = new StudentsController(context);

            // Act — "name_desc" sorts descending by LastName
            var result = controller.Index("name_desc", null, null, null);

            // Assert
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(
                Assert.IsType<ViewResult>(result).Model);
            Assert.Equal("Clark", model[0].LastName);
            Assert.Equal("Baker", model[1].LastName);
            Assert.Equal("Adams", model[2].LastName);
        }

        [Fact]
        public void Index_SortsByDateAscending()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            SeedStudents(context); // Adams=2023-09-01, Baker=2024-01-15, Clark=2023-06-01
            var controller = new StudentsController(context);

            // Act — "Date" sorts ascending by EnrollmentDate
            var result = controller.Index("Date", null, null, null);

            // Assert
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(
                Assert.IsType<ViewResult>(result).Model);
            Assert.Equal("Clark", model[0].LastName);  // 2023-06-01
            Assert.Equal("Adams", model[1].LastName);  // 2023-09-01
            Assert.Equal("Baker", model[2].LastName);  // 2024-01-15
        }

        [Fact]
        public void Index_SortsByDateDescending()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            SeedStudents(context);
            var controller = new StudentsController(context);

            // Act — "date_desc" sorts descending by EnrollmentDate
            var result = controller.Index("date_desc", null, null, null);

            // Assert
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(
                Assert.IsType<ViewResult>(result).Model);
            Assert.Equal("Baker", model[0].LastName);  // 2024-01-15
            Assert.Equal("Adams", model[1].LastName);  // 2023-09-01
            Assert.Equal("Clark", model[2].LastName);  // 2023-06-01
        }

        [Fact]
        public void Index_SetsViewBagSortParameters()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var controller = new StudentsController(context);

            // Act — default sort (empty sortOrder)
            controller.Index(null, null, null, null);

            // Assert — when sortOrder is empty, NameSortParm toggles to "name_desc"
            Assert.Equal("name_desc", controller.ViewBag.NameSortParm);
            Assert.Equal("Date", controller.ViewBag.DateSortParm);
        }

        [Fact]
        public void Index_SortOrderDate_DateSortParmToggles()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var controller = new StudentsController(context);

            // Act — sortOrder="Date" → DateSortParm should toggle to "date_desc"
            controller.Index("Date", null, null, null);

            // Assert
            Assert.Equal("date_desc", controller.ViewBag.DateSortParm);
            Assert.Equal("", controller.ViewBag.NameSortParm); // non-empty sortOrder → ""
        }

        [Fact]
        public void Index_PaginatesResults()
        {
            // Arrange — create 15 students, pageSize is 10
            using var context = TestDbContextFactory.Create();
            for (int i = 1; i <= 15; i++)
            {
                context.Students.Add(new Student
                {
                    LastName = $"Student{i:D2}",
                    FirstMidName = $"First{i}",
                    EnrollmentDate = new DateTime(2023, 1, 1)
                });
            }
            context.SaveChanges();
            var controller = new StudentsController(context);

            // Act — page 1
            var result1 = controller.Index(null, null, null, 1);
            var model1 = Assert.IsAssignableFrom<PaginatedList<Student>>(
                Assert.IsType<ViewResult>(result1).Model);

            // Assert — page 1 has 10 items
            Assert.Equal(10, model1.Count);
            Assert.True(model1.HasNextPage);
            Assert.False(model1.HasPreviousPage);
            Assert.Equal(2, model1.TotalPages);

            // Act — page 2
            var result2 = controller.Index(null, null, null, 2);
            var model2 = Assert.IsAssignableFrom<PaginatedList<Student>>(
                Assert.IsType<ViewResult>(result2).Model);

            // Assert — page 2 has 5 items
            Assert.Equal(5, model2.Count);
            Assert.False(model2.HasNextPage);
            Assert.True(model2.HasPreviousPage);
        }

        [Fact]
        public void Index_NewSearchString_ResetsPageToOne()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            SeedStudents(context);
            var controller = new StudentsController(context);

            // Act — pass a new searchString with page=5 → should reset to page 1
            var result = controller.Index(null, null, "Adams", 5);

            // Assert — ViewBag.CurrentFilter is set and page was reset
            Assert.Equal("Adams", controller.ViewBag.CurrentFilter);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(
                Assert.IsType<ViewResult>(result).Model);
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_NullSearchString_UsesCurrentFilter()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            SeedStudents(context);
            var controller = new StudentsController(context);

            // Act — searchString is null, currentFilter is "Baker"
            var result = controller.Index(null, "Baker", null, null);

            // Assert — uses currentFilter as searchString
            Assert.Equal("Baker", controller.ViewBag.CurrentFilter);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(
                Assert.IsType<ViewResult>(result).Model);
            Assert.Single(model);
            Assert.Equal("Baker", model[0].LastName);
        }

        #endregion

        #region Details Tests

        [Fact]
        public void Details_ReturnsStudent_WhenIdValid()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var student = new Student { LastName = "Test", FirstMidName = "User", EnrollmentDate = new DateTime(2023, 9, 1) };
            context.Students.Add(student);
            context.SaveChanges();
            var controller = new StudentsController(context);

            // Act
            var result = controller.Details(student.ID);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Student>(viewResult.Model);
            Assert.Equal("Test", model.LastName);
            Assert.Equal("User", model.FirstMidName);
            Assert.Equal(student.ID, model.ID);
        }

        [Fact]
        public void Details_ReturnsBadRequest_WhenIdNull()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var controller = new StudentsController(context);

            // Act
            var result = controller.Details(null);

            // Assert — returns StatusCodeResult(400)
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Details_IncludesEnrollmentsWithCourses()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
