using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests
    {
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly string _tempRoot;

        public CoursesControllerTests()
        {
            _tempRoot = Path.Combine(Path.GetTempPath(), "CoursesControllerTests_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(_tempRoot);

            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockEnv.Setup(e => e.WebRootPath).Returns(_tempRoot);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempRoot);

            _mockLogger = new Mock<ILogger<CoursesController>>();
        }

        private CoursesController CreateController(SchoolContext context)
        {
            return new CoursesController(context, _mockEnv.Object, _mockLogger.Object);
        }

        private static Department SeedDepartment(SchoolContext context, string name = "Engineering")
        {
            var dept = new Department
            {
                Name = name,
                Budget = 100000m,
                StartDate = new DateTime(2020, 1, 1)
            };
            context.Departments.Add(dept);
            context.SaveChanges();
            return dept;
        }

        private static Course SeedCourse(SchoolContext context, Department dept, int courseId = 1050, string title = "Chemistry")
        {
            var course = new Course
            {
                CourseID = courseId,
                Title = title,
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            context.Courses.Add(course);
            context.SaveChanges();
            return course;
        }

        private static Mock<IFormFile> CreateMockFormFile(string fileName, long length)
        {
            var mock = new Mock<IFormFile>();
            mock.Setup(f => f.FileName).Returns(fileName);
            mock.Setup(f => f.Length).Returns(length);
            mock.Setup(f => f.CopyTo(It.IsAny<Stream>()));
            return mock;
        }

        #region Index Tests

        [Fact]
        public void Index_ReturnsViewWithCourses()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            SeedCourse(context, dept, 1001, "Physics");
            SeedCourse(context, dept, 1002, "Math");
            var controller = CreateController(context);

            // Act
            var result = controller.Index();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
            Assert.Equal(2, model.Count);
            Assert.Contains(model, c => c.Title == "Physics");
            Assert.Contains(model, c => c.Title == "Math");
        }

        [Fact]
        public void Index_IncludesDepartmentData()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context, "Science");
            SeedCourse(context, dept, 2001, "Biology");
            var controller = CreateController(context);

            // Act
            var result = controller.Index();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
            Assert.Single(model);
            Assert.Equal("Science", model[0].Department.Name);
        }

        [Fact]
        public void Index_NoCourses_ReturnsEmptyList()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var controller = CreateController(context);

            // Act
            var result = controller.Index();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
            Assert.Empty(model);
        }

        #endregion

        #region Details Tests

        [Fact]
        public void Details_ReturnsCorrectCourse_WhenIdValid()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var course = SeedCourse(context, dept, 3001, "Algebra");
            var controller = CreateController(context);

            // Act
            var result = controller.Details(3001);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal(3001, model.CourseID);
            Assert.Equal("Algebra", model.Title);
            Assert.Equal(3, model.Credits);
            Assert.Equal(dept.DepartmentID, model.DepartmentID);
        }

        [Fact]
        public void Details_ReturnsBadRequest_WhenIdNull()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var controller = CreateController(context);

            // Act
            var result = controller.Details(null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Details_IncludesDepartmentNavigation()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context, "History");
            SeedCourse(context, dept, 4001, "Ancient History");
            var controller = CreateController(context);

            // Act
            var result = controller.Details(4001);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Course>(viewResult.Model);
            Assert.NotNull(model.Department);
            Assert.Equal("History", model.Department.Name);
        }

        #endregion

        #region Create GET Tests

        [Fact]
        public void Create_GET_PopulatesDepartmentDropDown()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            SeedDepartment(context, "Math");
            SeedDepartment(context, "Science");
            var controller = CreateController(context);

            // Act
            var result = controller.Create();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var selectList = Assert.IsType<SelectList>(controller.ViewBag.DepartmentID);
            Assert.Equal(2, selectList.Count());
        }

        [Fact]
        public void Create_GET_ReturnsNewCourseModel()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var controller = CreateController(context);

            // Act
            var result = controller.Create();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal(0, model.CourseID);
        }

        #endregion

        #region Create POST Tests

        [Fact]
        public void Create_POST_AddsCourse_WhenModelValid()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course
            {
                CourseID = 5001,
                Title = "New Course",
                Credits = 4,
                DepartmentID = dept.DepartmentID
            };

            // Act
            var result = controller.Create(course, null);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Equal(1, context.Courses.Count());
            var saved = context.Courses.Single();
            Assert.Equal("New Course", saved.Title);
            Assert.Equal(4, saved.Credits);
            Assert.Equal(5001, saved.CourseID);
        }

        [Fact]
        public void Create_POST_ReturnsView_WhenModelInvalid()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 5002, DepartmentID = dept.DepartmentID };

            // Act
            var result = controller.Create(course, null);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Course>(viewResult.Model);
            Assert.Equal(0, context.Courses.Count());
            Assert.NotNull(controller.ViewBag.DepartmentID);
        }

        [Fact]
        public void Create_POST_RejectsInvalidFileExtension()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course { CourseID = 5003, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFormFile("document.pdf", 1024);

            // Act
            var result = controller.Create(course, mockFile.Object);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
            var error = controller.ModelState["teachingMaterialImage"]!.Errors.Single();
            Assert.Contains("valid image file", error.ErrorMessage);
            Assert.Equal(0, context.Courses.Count());
        }

        [Fact]
        public void Create_POST_RejectsFileLargerThan5MB()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course { CourseID = 5004, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFormFile("large.jpg", 6 * 1024 * 1024); // 6 MB

            // Act
            var result = controller.Create(course, mockFile.Object);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
            var error = controller.ModelState["teachingMaterialImage"]!.Errors.Single();
            Assert.Contains("5MB", error.ErrorMessage);
            Assert.Equal(0, context.Courses.Count());
        }

        [Fact]
        public void Create_POST_AcceptsValidImageAndSaves()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course { CourseID = 5005, Title = "Art", Credits = 2, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFormFile("photo.png", 2048);

            // Act
            var result = controller.Create(course, mockFile.Object);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            var saved = context.Courses.Single();
            Assert.StartsWith("/Uploads/TeachingMaterials/course_5005_", saved.TeachingMaterialImagePath);
            Assert.EndsWith(".png", saved.TeachingMaterialImagePath);
        }

        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void Create_POST_AcceptsAllAllowedExtensions(string extension)
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course { CourseID = 5010 + extension.GetHashCode() % 1000, Title = "Test" + extension, Credits = 1, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFormFile("image" + extension, 1024);

            // Act
            var result = controller.Create(course, mockFile.Object);

            // Assert
            Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal(1, context.Courses.Count());
        }

        [Fact]
        public void Create_POST_FileExactly5MB_IsAccepted()
        {
            // Arrange — boundary: exactly 5 * 1024 * 1024 = 5242880 bytes
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course { CourseID = 5006, Title = "Boundary", Credits = 1, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFormFile("exact.jpg", 5 * 1024 * 1024);

            // Act
            var result = controller.Create(course, mockFile.Object);

            // Assert — exactly 5MB should pass (> check, not >=)
            Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal(1, context.Courses.Count());
        }

        [Fact]
        public void Create_POST_FileJustOver5MB_IsRejected()
        {
            // Arrange — 1 byte over
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course { CourseID = 5007, Title = "OverLimit", Credits = 1, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFormFile("over.jpg", 5 * 1024 * 1024 + 1);

            // Act
            var result = controller.Create(course, mockFile.Object);

            // Assert
            Assert.IsType<ViewResult>(result);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Equal(0, context.Courses.Count());
        }

        #endregion

        #region Edit GET Tests

        [Fact]
        public void Edit_GET_ReturnsCourse_WhenIdValid()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var course = SeedCourse(context, dept, 6001, "Calculus");
            var controller = CreateController(context);

            // Act
            var result = controller.Edit(6001);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal(6001, model.CourseID);
            Assert.Equal("Calculus", model.Title);
            Assert.NotNull(controller.ViewBag.DepartmentID);
        }

        [Fact]
        public void Edit_GET_ReturnsBadRequest_WhenIdNull()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var controller = CreateController(context);

            // Act
            var result = controller.Edit((int?)null);

            // Assert
            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_GET_ReturnsNotFound_WhenCourseNotFound()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var controller = CreateController(context);

            // Act
            var result = controller.Edit(99999);

            // Assert
            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_GET_PopulatesDepartmentSelectList()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept1 = SeedDepartment(context, "Dept A");
            var dept2 = SeedDepartment(context, "Dept B");
            SeedCourse(context, dept1, 6002, "Course X");
            var controller = CreateController(context);

            // Act
            var result = controller.Edit(6002);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var selectList = Assert.IsType<SelectList>(controller.ViewBag.DepartmentID);
            Assert.Equal(2, selectList.Count());
        }

        #endregion

        #region Edit POST Tests

        [Fact]
        public void Edit_POST_UpdatesCourse_WhenValid()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            SeedCourse(context, dept, 7001, "OldTitle");
            // Detach so EF doesn't track the seeded entity
            context.ChangeTracker.Clear();
            var controller = CreateController(context);
            var updated = new Course { CourseID = 7001, Title = "NewTitle", Credits = 5, DepartmentID = dept.DepartmentID };

            // Act
            var result = controller.Edit(updated, null);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            context.ChangeTracker.Clear();
            var saved = context.Courses.Find(7001);
            Assert.Equal("NewTitle", saved!.Title);
            Assert.Equal(5, saved.Credits);
        }

        [Fact]
        public void Edit_POST_ReturnsView_WhenModelInvalid()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 7002, DepartmentID = dept.DepartmentID };

            // Act
            var result = controller.Edit(course, null);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.NotNull(controller.ViewBag.DepartmentID);
        }

        [Fact]
        public void Edit_POST_RejectsInvalidFileExtension()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            SeedCourse(context, dept, 7003, "Existing");
            context.ChangeTracker.Clear();
            var controller = CreateController(context);
            var course = new Course { CourseID = 7003, Title = "Existing", Credits = 3, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFormFile("bad.exe", 1024);

            // Act
            var result = controller.Edit(course, mockFile.Object);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_POST_RejectsOversizedFile()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            SeedCourse(context, dept, 7004, "Existing");
