        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly string _tempRoot;

        public CoursesControllerTests()
        {
            _tempRoot = Path.Combine(Path.GetTempPath(), "CoursesControllerTests_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(_tempRoot);

            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockEnv.Setup(e => e.WebRootPath).Returns(_tempRoot);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempRoot);

            _mockLogger = new Mock<ILogger<CoursesController>>();
        }

        private CoursesController CreateController(SchoolContext context)
        {
            return new CoursesController(context, _mockEnv.Object, _mockLogger.Object);
        }

        private static Department SeedDepartment(SchoolContext context, string name = "Engineering")
        {
            var dept = new Department
            {
                Name = name,
                Budget = 100000m,
                StartDate = new DateTime(2020, 1, 1)
            };
            context.Departments.Add(dept);
            context.SaveChanges();
            return dept;
        }

        private static Course SeedCourse(SchoolContext context, Department dept, int courseId = 1050, string title = "Chemistry")
        {
            var course = new Course
            {
                CourseID = courseId,
                Title = title,
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            context.Courses.Add(course);
            context.SaveChanges();
            return course;
        }

        private static Mock<IFormFile> CreateMockFormFile(string fileName, long length)
        {
            var mock = new Mock<IFormFile>();
            mock.Setup(f => f.FileName).Returns(fileName);
            mock.Setup(f => f.Length).Returns(length);
            mock.Setup(f => f.CopyTo(It.IsAny<Stream>()));
            return mock;
        }

