using System;
using System.Collections.Generic;
using System.Dynamic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Newtonsoft.Json;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests
    {
        /// <summary>
        /// Drains the static NotificationService queue to prevent cross-test interference.
        /// The queue is static (ConcurrentQueue) shared across all NotificationService instances.
        /// </summary>
        private static void DrainNotificationQueue()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        #region Index Tests

        [Fact]
        public void Index_ReturnsView()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var controller = new NotificationsController(context);

            // Act
            var result = controller.Index();

            // Assert
            Assert.IsType<ViewResult>(result);
        }

        #endregion

        #region GetNotifications Tests

        [Fact]
        public void GetNotifications_ReturnsEmptyList_WhenNoNotifications()
        {
            // Arrange
            DrainNotificationQueue();
            using var context = TestDbContextFactory.Create();
            var controller = new NotificationsController(context);

            // Act
            var result = controller.GetNotifications();

            // Assert
            Assert.IsType<JsonResult>(result);
            var json = result.Value;
            Assert.NotNull(json);
            // Use reflection to check anonymous type properties
            var successProp = json.GetType().GetProperty("success");
            var countProp = json.GetType().GetProperty("count");
            Assert.NotNull(successProp);
            Assert.NotNull(countProp);
            Assert.True((bool)successProp.GetValue(json)!);
            Assert.Equal(0, (int)countProp.GetValue(json)!);
        }

        [Fact]
        public void GetNotifications_ReturnsNotifications_WhenQueued()
        {
            // Arrange
            DrainNotificationQueue();
            var svc = new NotificationService();
            svc.SendNotification("Student", "1", EntityOperation.CREATE, "TestUser");
            svc.SendNotification("Course", "42", EntityOperation.UPDATE, "TestUser");

            using var context = TestDbContextFactory.Create();
            var controller = new NotificationsController(context);

            // Act
            var result = controller.GetNotifications();

            // Assert
            var json = result.Value;
            var successProp = json!.GetType().GetProperty("success");
            var countProp = json.GetType().GetProperty("count");
            var notificationsProp = json.GetType().GetProperty("notifications");
            Assert.True((bool)successProp!.GetValue(json)!);
            var count = (int)countProp!.GetValue(json)!;
            Assert.Equal(2, count);
            var notifications = notificationsProp!.GetValue(json) as List<Notification>;
            Assert.NotNull(notifications);
            Assert.Equal(2, notifications.Count);
            Assert.Equal("Student", notifications[0].EntityType);
            Assert.Equal("Course", notifications[1].EntityType);
        }

        [Fact]
        public void GetNotifications_LimitsTo10_WhenMoreQueued()
        {
            // Arrange
            DrainNotificationQueue();
            var svc = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                svc.SendNotification("Entity", i.ToString(), EntityOperation.CREATE, "User");
            }

            using var context = TestDbContextFactory.Create();
            var controller = new NotificationsController(context);

            // Act
            var result = controller.GetNotifications();

            // Assert
            var json = result.Value;
            var countProp = json!.GetType().GetProperty("count");
            var count = (int)countProp!.GetValue(json)!;
            Assert.Equal(10, count);

            // 5 should remain in the queue
            var remaining = new List<Notification>();
            Notification n;
            while ((n = svc.ReceiveNotification()) != null) remaining.Add(n);
            Assert.Equal(5, remaining.Count);
        }

        [Fact]
        public void GetNotifications_DrainsQueue_ConsecutiveCallsReturnDifferentItems()
        {
            // Arrange
            DrainNotificationQueue();
            var svc = new NotificationService();
            svc.SendNotification("Student", "1", EntityOperation.CREATE, "User");
            svc.SendNotification("Student", "2", EntityOperation.DELETE, "User");

            using var context = TestDbContextFactory.Create();
            var controller = new NotificationsController(context);

            // Act — first call dequeues all
            var result1 = controller.GetNotifications();
            var count1 = (int)result1.Value!.GetType().GetProperty("count")!.GetValue(result1.Value)!;

            // Second call should get nothing
            var result2 = controller.GetNotifications();
            var count2 = (int)result2.Value!.GetType().GetProperty("count")!.GetValue(result2.Value)!;

            // Assert
            Assert.Equal(2, count1);
            Assert.Equal(0, count2);
        }

        #endregion

        #region MarkAsRead Tests

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            // Arrange
            DrainNotificationQueue();
            using var context = TestDbContextFactory.Create();
            var controller = new NotificationsController(context);

            // Act — MarkAsRead is a no-op for in-memory implementation, but should return success
            var result = controller.MarkAsRead(1);

            // Assert
            Assert.IsType<JsonResult>(result);
            var json = result.Value;
            var successProp = json!.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(json)!);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess_ForAnyId()
        {
            // Arrange
            DrainNotificationQueue();
            using var context = TestDbContextFactory.Create();
            var controller = new NotificationsController(context);

            // Act — with arbitrary IDs (no-op implementation doesn't validate)
            var result1 = controller.MarkAsRead(0);
            var result2 = controller.MarkAsRead(-1);
            var result3 = controller.MarkAsRead(999999);

            // Assert — all should succeed since MarkAsRead is a no-op
            Assert.True((bool)result1.Value!.GetType().GetProperty("success")!.GetValue(result1.Value)!);
            Assert.True((bool)result2.Value!.GetType().GetProperty("success")!.GetValue(result2.Value)!);
            Assert.True((bool)result3.Value!.GetType().GetProperty("success")!.GetValue(result3.Value)!);
        }

        #endregion
    }
}

