using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests
    {
        /// <summary>
        /// Seeds a department, two courses under that department, and two instructors.
        /// Instructor "Smith" has an office and is assigned to course 1001.
        /// Instructor "Jones" has no office and no course assignments.
        /// Course 1001 has one enrollment (student "Doe" with Grade.A).
        /// </summary>
        private static (Instructor smith, Instructor jones, Course course1, Course course2) SeedInstructorData(SchoolContext context)
        {
            var dept = new Department
            {
                Name = "Science",
                Budget = 200000,
                StartDate = new DateTime(2020, 1, 1)
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course1 = new Course
            {
                CourseID = 1001,
                Title = "Physics",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            var course2 = new Course
            {
                CourseID = 1002,
                Title = "Biology",
                Credits = 4,
                DepartmentID = dept.DepartmentID,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Courses.AddRange(course1, course2);
            context.SaveChanges();

            var smith = new Instructor
            {
                LastName = "Smith",
                FirstMidName = "John",
                HireDate = new DateTime(2010, 8, 1),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
            };
            var jones = new Instructor
            {
                LastName = "Jones",
                FirstMidName = "Jane",
                HireDate = new DateTime(2015, 1, 15),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Instructors.AddRange(smith, jones);
            context.SaveChanges();

            // Assign Smith to course 1001
            var ca = new CourseAssignment { InstructorID = smith.ID, CourseID = course1.CourseID };
            context.CourseAssignments.Add(ca);
            context.SaveChanges();

            // Add a student enrollment in course 1001 so Index drill-down works
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Alice",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };
            context.Students.Add(student);
            context.SaveChanges();

            context.Enrollments.Add(new Enrollment
            {
                StudentID = student.ID,
                CourseID = course1.CourseID,
                Grade = Grade.A
            });
            context.SaveChanges();

            return (smith, jones, course1, course2);
        }

        #region Index Tests

        [Fact]
        public void Index_ReturnsViewWithInstructors()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var (smith, jones, _, _) = SeedInstructorData(context);
            var controller = new InstructorsController(context);

            // Act
            var result = controller.Index(null, null);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            var instructors = model.Instructors.ToList();
            Assert.Equal(2, instructors.Count);
            // Ordered by LastName: Jones before Smith
            Assert.Equal("Jones", instructors[0].LastName);
            Assert.Equal("Smith", instructors[1].LastName);
        }

        [Fact]
        public void Index_IncludesOfficeAssignments()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var (smith, jones, _, _) = SeedInstructorData(context);
            var controller = new InstructorsController(context);

            // Act
            var result = controller.Index(null, null);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            var instructors = model.Instructors.ToList();
            // Smith has office, Jones does not
            var smithResult = instructors.Single(i => i.LastName == "Smith");
            var jonesResult = instructors.Single(i => i.LastName == "Jones");
            Assert.NotNull(smithResult.OfficeAssignment);
            Assert.Equal("Room 101", smithResult.OfficeAssignment.Location);
            Assert.Null(jonesResult.OfficeAssignment);
        }

        [Fact]
        public void Index_IncludesCourseAssignments()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var (smith, jones, _, _) = SeedInstructorData(context);
            var controller = new InstructorsController(context);

            // Act
            var result = controller.Index(null, null);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            var smithResult = model.Instructors.Single(i => i.LastName == "Smith");
            Assert.Single(smithResult.CourseAssignments);
            Assert.Equal(1001, smithResult.CourseAssignments.First().CourseID);
        }

        [Fact]
        public void Index_WithSelectedInstructor_ShowsCourses()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var (smith, _, course1, _) = SeedInstructorData(context);
            var controller = new InstructorsController(context);

            // Act — select Smith by ID
            var result = controller.Index(smith.ID, null);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
            Assert.NotNull(model.Courses);
            var courses = model.Courses.ToList();
