using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_SeedsStudents_WhenDatabaseEmpty()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(8, context.Students.Count());
            // Verify specific student data to ensure seed is correct
            var carson = context.Students.Single(s => s.LastName == "Alexander");
            Assert.Equal("Carson", carson.FirstMidName);
            Assert.Equal(DateTime.Parse("2010-09-01"), carson.EnrollmentDate);
        }

        [Fact]
        public void Initialize_SeedsInstructors_WhenDatabaseEmpty()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(5, context.Instructors.Count());
            // Verify specific instructor data
            var kim = context.Instructors.Single(i => i.LastName == "Abercrombie");
            Assert.Equal("Kim", kim.FirstMidName);
            Assert.Equal(DateTime.Parse("1995-03-11"), kim.HireDate);
            // Verify all expected last names
            var lastNames = context.Instructors.Select(i => i.LastName).OrderBy(n => n).ToList();
            Assert.Equal(new[] { "Abercrombie", "Fakhouri", "Harui", "Kapoor", "Zheng" }, lastNames);
        }

        [Fact]
        public void Initialize_SeedsCourses_WhenDatabaseEmpty()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(7, context.Courses.Count());
            // Verify specific courses by known IDs
            var chemistry = context.Courses.Single(c => c.CourseID == 1050);
            Assert.Equal("Chemistry", chemistry.Title);
            Assert.Equal(3, chemistry.Credits);
            var calculus = context.Courses.Single(c => c.CourseID == 1045);
            Assert.Equal("Calculus", calculus.Title);
            Assert.Equal(4, calculus.Credits);
        }

        [Fact]
        public void Initialize_SeedsDepartments_WhenDatabaseEmpty()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(4, context.Departments.Count());
            var deptNames = context.Departments.Select(d => d.Name).OrderBy(n => n).ToList();
            Assert.Equal(new[] { "Economics", "Engineering", "English", "Mathematics" }, deptNames);
            // Verify budget for a specific department
            var english = context.Departments.Single(d => d.Name == "English");
            Assert.Equal(350000, english.Budget);
            // Verify department-instructor linkage
            var mathDept = context.Departments.Single(d => d.Name == "Mathematics");
            var fakhouri = context.Instructors.Single(i => i.LastName == "Fakhouri");
            Assert.Equal(fakhouri.ID, mathDept.InstructorID);
        }

        [Fact]
        public void Initialize_SeedsEnrollments_WhenDatabaseEmpty()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(11, context.Enrollments.Count());
            // Verify a specific enrollment
            var alexander = context.Students.Single(s => s.LastName == "Alexander");
            var chemistryCourse = context.Courses.Single(c => c.Title == "Chemistry");
            var enrollment = context.Enrollments.Single(
                e => e.StudentID == alexander.ID && e.CourseID == chemistryCourse.CourseID);
            Assert.Equal(Grade.A, enrollment.Grade);
            // Verify null grade exists (Anand in Chemistry)
            var anand = context.Students.Single(s => s.LastName == "Anand");
            var anandChemistry = context.Enrollments.Single(
                e => e.StudentID == anand.ID && e.CourseID == chemistryCourse.CourseID);
            Assert.Null(anandChemistry.Grade);
        }

        [Fact]
        public void Initialize_DoesNotReseed_WhenDataExists()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            // First initialization
            DbInitializer.Initialize(context);
            var studentCount = context.Students.Count();
            var courseCount = context.Courses.Count();
            var enrollmentCount = context.Enrollments.Count();

            // Act — second initialization should be idempotent
            DbInitializer.Initialize(context);

            // Assert — counts should not change
            Assert.Equal(studentCount, context.Students.Count());
            Assert.Equal(courseCount, context.Courses.Count());
            Assert.Equal(enrollmentCount, context.Enrollments.Count());
        }

        [Fact]
        public void Initialize_SeedsOfficeAssignments_WhenDatabaseEmpty()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(3, context.OfficeAssignments.Count());
            var fakhouri = context.Instructors.Single(i => i.LastName == "Fakhouri");
            var office = context.OfficeAssignments.Find(fakhouri.ID);
            Assert.NotNull(office);
            Assert.Equal("Smith 17", office.Location);
        }

        [Fact]
        public void Initialize_SeedsCourseAssignments_WhenDatabaseEmpty()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(8, context.CourseAssignments.Count());
            // Verify Abercrombie teaches Composition and Literature
            var abercrombie = context.Instructors.Single(i => i.LastName == "Abercrombie");
            var abercrombieCourses = context.CourseAssignments
                .Where(ca => ca.InstructorID == abercrombie.ID)
                .Select(ca => ca.CourseID)
                .ToList();
            Assert.Equal(2, abercrombieCourses.Count);
            var composition = context.Courses.Single(c => c.Title == "Composition");
            var literature = context.Courses.Single(c => c.Title == "Literature");
            Assert.Contains(composition.CourseID, abercrombieCourses);
            Assert.Contains(literature.CourseID, abercrombieCourses);
        }
    }
}

