 using Xunit;

 namespace ContosoUniversity.Tests.Controllers
 {
     public class DepartmentsControllerTests
     {
         private static DepartmentsController CreateController(SchoolContext context)
         {
             return new DepartmentsController(context);
         }

         private static Instructor SeedInstructor(SchoolContext context, string lastName = "Smith", string firstName = "John")
         {
             var instructor = new Instructor
             {
                 LastName = lastName,
                 FirstMidName = firstName,
                 HireDate = new DateTime(2015, 8, 1)
             };
             context.Instructors.Add(instructor);
             context.SaveChanges();
             return instructor;
         }

         private static Department SeedDepartment(SchoolContext context, string name = "Engineering", Instructor? admin = null, decimal budget = 100000m)
         {
             var dept = new Department
             {
                 Name = name,
                 Budget = budget,
                 StartDate = new DateTime(2020, 1, 1),
                 InstructorID = admin?.ID
             };
             context.Departments.Add(dept);
             context.SaveChanges();
             return dept;
         }

         #region Index Tests

         [Fact]
         public void Index_ReturnsViewWithDepartments()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             SeedDepartment(context, "Math");
             SeedDepartment(context, "Science");
             SeedDepartment(context, "Arts");
             var controller = CreateController(context);

             // Act
             var result = controller.Index();

             // Assert
             var viewResult = Assert.IsType<ViewResult>(result);
             var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
             Assert.Equal(3, model.Count);
             Assert.Contains(model, d => d.Name == "Math");
             Assert.Contains(model, d => d.Name == "Science");
             Assert.Contains(model, d => d.Name == "Arts");
         }

         [Fact]
         public void Index_IncludesAdministratorData()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var instructor = SeedInstructor(context, "Doe", "Jane");
             SeedDepartment(context, "English", instructor);
             var controller = CreateController(context);

             // Act
             var result = controller.Index();

             // Assert
             var viewResult = Assert.IsType<ViewResult>(result);
             var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
             Assert.Single(model);
             Assert.NotNull(model[0].Administrator);
             Assert.Equal("Doe", model[0].Administrator.LastName);
             Assert.Equal("Jane", model[0].Administrator.FirstMidName);
         }

         [Fact]
         public void Index_NoDepartments_ReturnsEmptyList()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var controller = CreateController(context);

             // Act
             var result = controller.Index();

             // Assert
             var viewResult = Assert.IsType<ViewResult>(result);
             var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
             Assert.Empty(model);
         }

         #endregion

         #region Details Tests

         [Fact]
         public void Details_ReturnsDepartment_WhenIdValid()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var dept = SeedDepartment(context, "Physics", budget: 250000m);
             var controller = CreateController(context);

             // Act
             var result = controller.Details(dept.DepartmentID);

             // Assert
             var viewResult = Assert.IsType<ViewResult>(result);
             var model = Assert.IsType<Department>(viewResult.Model);
             Assert.Equal("Physics", model.Name);
             Assert.Equal(250000m, model.Budget);
             Assert.Equal(dept.DepartmentID, model.DepartmentID);
         }

         [Fact]
         public void Details_ReturnsBadRequest_WhenIdNull()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var controller = CreateController(context);

             // Act
             var result = controller.Details(null);

             // Assert
             var statusResult = Assert.IsType<StatusCodeResult>(result);
             Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
         }

         [Fact]
         public void Details_ReturnsNotFound_WhenDepartmentNotFound()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var controller = CreateController(context);

             // Act
             var result = controller.Details(99999);

             // Assert
             Assert.IsType<NotFoundResult>(result);
         }

         #endregion

         #region Create GET Tests

         [Fact]
         public void Create_GET_PopulatesInstructorDropDown()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             SeedInstructor(context, "Alpha", "Ann");
             SeedInstructor(context, "Beta", "Bob");
             var controller = CreateController(context);

             // Act
             var result = controller.Create();

             // Assert
             var viewResult = Assert.IsType<ViewResult>(result);
             SelectList selectList = (SelectList)controller.ViewBag.InstructorID;
             Assert.Equal(2, selectList.Cast<SelectListItem>().Count());
         }

         [Fact]
         public void Create_GET_ReturnsView()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var controller = CreateController(context);

             // Act
             var result = controller.Create();

             // Assert
             Assert.IsType<ViewResult>(result);
         }

         #endregion

         #region Create POST Tests

         [Fact]
         public void Create_POST_AddsDepartment_WhenModelValid()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var instructor = SeedInstructor(context);
             var controller = CreateController(context);
             var department = new Department
             {
                 Name = "New Dept",
                 Budget = 50000m,
                 StartDate = new DateTime(2024, 1, 1),
                 InstructorID = instructor.ID
             };

             // Act
             var result = controller.Create(department);

             // Assert
             var redirect = Assert.IsType<RedirectToActionResult>(result);
             Assert.Equal("Index", redirect.ActionName);
             Assert.Equal(1, context.Departments.Count());
             var saved = context.Departments.Single();
             Assert.Equal("New Dept", saved.Name);
             Assert.Equal(50000m, saved.Budget);
             Assert.Equal(instructor.ID, saved.InstructorID);
         }

         [Fact]
         public void Create_POST_ReturnsView_WhenModelInvalid()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             SeedInstructor(context);
             var controller = CreateController(context);
             controller.ModelState.AddModelError("Name", "Required");
             var department = new Department { Budget = 10000m, StartDate = DateTime.Now };

             // Act
             var result = controller.Create(department);

             // Assert
             var viewResult = Assert.IsType<ViewResult>(result);
             Assert.IsType<Department>(viewResult.Model);
             Assert.Equal(0, context.Departments.Count());
             Assert.NotNull(controller.ViewBag.InstructorID);
         }

         [Fact]
         public void Create_POST_DepartmentWithNoAdministrator_Succeeds()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var controller = CreateController(context);
             var department = new Department
             {
                 Name = "No Admin",
                 Budget = 75000m,
                 StartDate = new DateTime(2023, 6, 1),
                 InstructorID = null
             };

             // Act
             var result = controller.Create(department);

             // Assert
             var redirect = Assert.IsType<RedirectToActionResult>(result);
             Assert.Equal("Index", redirect.ActionName);
             var saved = context.Departments.Single();
             Assert.Null(saved.InstructorID);
             Assert.Equal("No Admin", saved.Name);
         }

         #endregion

         #region Edit GET Tests

         [Fact]
         public void Edit_GET_ReturnsDepartment_WhenIdValid()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var instructor = SeedInstructor(context, "Teach", "Tom");
             var dept = SeedDepartment(context, "History", instructor, 200000m);
             var controller = CreateController(context);

             // Act
             var result = controller.Edit(dept.DepartmentID);

             // Assert
             var viewResult = Assert.IsType<ViewResult>(result);
             var model = Assert.IsType<Department>(viewResult.Model);
             Assert.Equal("History", model.Name);
             Assert.Equal(200000m, model.Budget);
             Assert.NotNull(controller.ViewBag.InstructorID);
         }

         [Fact]
         public void Edit_GET_ReturnsBadRequest_WhenIdNull()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var controller = CreateController(context);

             // Act
             var result = controller.Edit((int?)null);

             // Assert
             var statusResult = Assert.IsType<StatusCodeResult>(result);
             Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
         }

         [Fact]
         public void Edit_GET_ReturnsNotFound_WhenDepartmentNotFound()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var controller = CreateController(context);

             // Act
             var result = controller.Edit(99999);

             // Assert
             Assert.IsType<NotFoundResult>(result);
         }

         [Fact]
         public void Edit_GET_PopulatesInstructorSelectList()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var inst1 = SeedInstructor(context, "One", "Inst");
             var inst2 = SeedInstructor(context, "Two", "Inst");
             var dept = SeedDepartment(context, "CS", inst1);
             var controller = CreateController(context);

             // Act
             var result = controller.Edit(dept.DepartmentID);

             // Assert
             SelectList selectList = (SelectList)controller.ViewBag.InstructorID;
             Assert.Equal(2, selectList.Cast<SelectListItem>().Count());
         }

         #endregion

         #region Edit POST Tests

         [Fact]
         public void Edit_POST_UpdatesDepartment_WhenValid()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var instructor = SeedInstructor(context);
             var dept = SeedDepartment(context, "OldName", instructor, 100000m);
             context.ChangeTracker.Clear();
             var controller = CreateController(context);
             var updated = new Department
             {
                 DepartmentID = dept.DepartmentID,
                 Name = "NewName",
                 Budget = 999999m,
                 StartDate = new DateTime(2025, 1, 1),
                 InstructorID = instructor.ID
             };

             // Act
             var result = controller.Edit(updated);

             // Assert
             var redirect = Assert.IsType<RedirectToActionResult>(result);
             Assert.Equal("Index", redirect.ActionName);
             context.ChangeTracker.Clear();
             var saved = context.Departments.Find(dept.DepartmentID);
             Assert.Equal("NewName", saved!.Name);
             Assert.Equal(999999m, saved.Budget);
         }

         [Fact]
         public void Edit_POST_ReturnsView_WhenModelInvalid()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             SeedInstructor(context);
             var controller = CreateController(context);
             controller.ModelState.AddModelError("Name", "Required");
             var department = new Department { DepartmentID = 1 };

             // Act
             var result = controller.Edit(department);

             // Assert
             var viewResult = Assert.IsType<ViewResult>(result);
             Assert.NotNull(controller.ViewBag.InstructorID);
         }

         #endregion

         #region Delete GET Tests

         [Fact]
         public void Delete_GET_ReturnsDepartment_WhenIdValid()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var dept = SeedDepartment(context, "ToDelete", budget: 30000m);
             var controller = CreateController(context);

             // Act
             var result = controller.Delete(dept.DepartmentID);

             // Assert
             var viewResult = Assert.IsType<ViewResult>(result);
             var model = Assert.IsType<Department>(viewResult.Model);
             Assert.Equal("ToDelete", model.Name);
             Assert.Equal(30000m, model.Budget);
         }

         [Fact]
         public void Delete_GET_ReturnsBadRequest_WhenIdNull()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var controller = CreateController(context);

             // Act
             var result = controller.Delete(null);

             // Assert
             var statusResult = Assert.IsType<StatusCodeResult>(result);
             Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
         }

         [Fact]
         public void Delete_GET_ReturnsNotFound_WhenDepartmentNotFound()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var controller = CreateController(context);

             // Act
             var result = controller.Delete(99999);

             // Assert
             Assert.IsType<NotFoundResult>(result);
         }

         #endregion

         #region DeleteConfirmed Tests

         [Fact]
         public void DeleteConfirmed_RemovesDepartment()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var dept = SeedDepartment(context, "Bye");
             var controller = CreateController(context);

             // Act
             var result = controller.DeleteConfirmed(dept.DepartmentID);

             // Assert
             var redirect = Assert.IsType<RedirectToActionResult>(result);
             Assert.Equal("Index", redirect.ActionName);
             Assert.Equal(0, context.Departments.Count());
         }

         [Fact]
         public void DeleteConfirmed_WithMultipleDepartments_RemovesOnlyTargeted()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var keep = SeedDepartment(context, "Keep", budget: 50000m);
             var remove = SeedDepartment(context, "Remove", budget: 60000m);
             var controller = CreateController(context);

             // Act
             var result = controller.DeleteConfirmed(remove.DepartmentID);

             // Assert
             Assert.IsType<RedirectToActionResult>(result);
             Assert.Equal(1, context.Departments.Count());
             var remaining = context.Departments.Single();
             Assert.Equal("Keep", remaining.Name);
             Assert.Equal(50000m, remaining.Budget);
         }

         [Fact]
         public void DeleteConfirmed_DepartmentWithAdministrator_Succeeds()
         {
             // Arrange
             using var context = TestDbContextFactory.Create();
             var instructor = SeedInstructor(context, "Admin", "Dean");
             var dept = SeedDepartment(context, "WithAdmin", instructor);
             var controller = CreateController(context);

             // Act
             var result = controller.DeleteConfirmed(dept.DepartmentID);

             // Assert
             var redirect = Assert.IsType<RedirectToActionResult>(result);
             Assert.Equal("Index", redirect.ActionName);
             Assert.Equal(0, context.Departments.Count());
             // Instructor should still exist
             Assert.Equal(1, context.Instructors.Count());
         }

         #endregion
     }
 }

