        public void Create_PageIndex_Zero_SkipsNegativeCount_ReturnsItems()
        {
            // Arrange — pageIndex=0, pageSize=3, 6 items
            // Skip((0-1)*3) = Skip(-3). LINQ Skip with negative → skips 0.
            var source = Enumerable.Range(1, 6).AsQueryable();

