            // Assert — Skip(-3) skips nothing, Take(3) returns first 3
            Assert.Equal(3, result.Count);
            Assert.Equal(new[] { 1, 2, 3 }, result.ToArray());
            Assert.Equal(0, result.PageIndex);
            Assert.Equal(2, result.TotalPages); // ceil(6/3) = 2
            Assert.False(result.HasPreviousPage); // pageIndex 0 is NOT > 1
            Assert.True(result.HasNextPage); // pageIndex 0 < TotalPages 2
        }

