        [Fact]
        public void GetNotifications_NotificationHasCorrectEntityType_And_Operation()
        {
            // Arrange
            DrainNotificationQueue();
            var svc = new NotificationService();
            svc.SendNotification("Instructor", "42", "Dr. Smith", EntityOperation.UPDATE, "AdminUser");

            using var context = TestDbContextFactory.Create();
            var controller = new NotificationsController(context);

            // Act
            var result = controller.GetNotifications();

            // Assert
            var json = result.Value;
            var notificationsProp = json!.GetType().GetProperty("notifications");
            var notifications = notificationsProp!.GetValue(json) as List<Notification>;
            Assert.NotNull(notifications);
            Assert.Single(notifications);
            var notification = notifications[0];
            Assert.Equal("Instructor", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Equal("AdminUser", notification.CreatedBy);
            Assert.Contains("Dr. Smith", notification.Message);
            Assert.Contains("updated", notification.Message);
            Assert.False(notification.IsRead);
        }

