        #region Create POST — File Upload Exception Handling Tests

        [Fact]
        public void Create_POST_FileUploadException_ReturnsViewWithError()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course { CourseID = 5020, Title = "ExTest", Credits = 2, DepartmentID = dept.DepartmentID };

            // Create a mock file that throws on CopyTo
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(1024);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>())).Throws(new IOException("Disk full"));

            // Act
            var result = controller.Create(course, mockFile.Object);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
            var error = controller.ModelState["teachingMaterialImage"]!.Errors.Single();
            Assert.Contains("Error uploading file", error.ErrorMessage);
            Assert.Contains("Disk full", error.ErrorMessage);
            Assert.Equal(0, context.Courses.Count()); // Course was NOT saved
        }

        [Fact]
        public void Create_POST_NoFile_SavesCourseWithoutImage()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course { CourseID = 5021, Title = "NoImage", Credits = 3, DepartmentID = dept.DepartmentID };

            // Act — null file
            var result = controller.Create(course, null);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            var saved = context.Courses.Single();
            Assert.Equal("NoImage", saved.Title);
            Assert.Null(saved.TeachingMaterialImagePath);
        }

        [Fact]
        public void Create_POST_ZeroLengthFile_SavesCourseWithoutImage()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var controller = CreateController(context);
            var course = new Course { CourseID = 5022, Title = "ZeroFile", Credits = 1, DepartmentID = dept.DepartmentID };
