            mockFile.Setup(f => f.Length).Returns(2048);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>())).Throws(new IOException("Permission denied"));

            // Act
            var result = controller.Edit(course, mockFile.Object);

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
            var error = controller.ModelState["teachingMaterialImage"]!.Errors.Single();
            Assert.Contains("Error uploading file", error.ErrorMessage);
            Assert.Contains("Permission denied", error.ErrorMessage);
        }

        [Fact]
        public void Edit_POST_NoFile_UpdatesCourseWithoutChangingImage()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var dept = SeedDepartment(context);
            var course = SeedCourse(context, dept, 7011, "WithPath");
            course.TeachingMaterialImagePath = "/Uploads/TeachingMaterials/old.jpg";
            context.SaveChanges();
            context.ChangeTracker.Clear();
            var controller = CreateController(context);
            var updated = new Course
            {
