            var result = controller.Edit(updated, null);

            // Assert
            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            context.ChangeTracker.Clear();
            var saved = context.Courses.Find(7011);
            Assert.Equal("UpdatedTitle", saved!.Title);
            Assert.Equal(4, saved.Credits);
            Assert.Equal("/Uploads/TeachingMaterials/old.jpg", saved.TeachingMaterialImagePath);
        }

