    // Assert
    var statusResult = Assert.IsType<StatusCodeResult>(result);
    Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
}

[Fact]
public async Task Edit_POST_ReturnsView_WhenTryUpdateModelFails()
{
    // Arrange
    using var context = TestDbContextFactory.Create();
    var (smith, _, _, _) = SeedInstructorData(context);

    var controller = new InstructorsController(context);
    // Without HttpContext, TryUpdateModelAsync cannot bind and will throw.
    // Set up a DefaultHttpContext so the method can run but TryUpdateModelAsync returns false
    // because there's no model binder infrastructure.
    controller.ControllerContext = new Microsoft.AspNetCore.Mvc.ControllerContext
    {
        HttpContext = new Microsoft.AspNetCore.Http.DefaultHttpContext()
    };
    // TryUpdateModelAsync needs these services - without them it throws.
    // We catch that: the controller has a try path, but the base TryUpdateModelAsync
    // will fail, causing the method to fall through to return View.
    // Actually, we need to provide minimum MVC services for TryUpdateModelAsync.
    var services = new Microsoft.Extensions.DependencyInjection.ServiceCollection();
    services.AddLogging();
    services.AddMvcCore();
    var sp = services.BuildServiceProvider();
    controller.ControllerContext.HttpContext.RequestServices = sp;

    // Act — no form data, so TryUpdateModelAsync binds nothing but returns true
    // The instructor keeps its DB values. Since OfficeAssignment is "Room 101" (non-empty),
    // it won't be cleared. selectedCourses is null, so all courses are removed.
    var result = await controller.Edit(smith.ID, null);

    // Assert — since TryUpdateModelAsync returns true with no form data,
    // the method proceeds through the success path (save + redirect)
    var redirect = Assert.IsType<RedirectToActionResult>(result);
    Assert.Equal("Index", redirect.ActionName);
}

