[Fact]
public async Task Edit_POST_ClearsOfficeAssignment_WhenLocationEmptyString()
{
    // Arrange
    using var context = TestDbContextFactory.Create();
    var (smith, _, _, _) = SeedInstructorData(context);
    // Smith has OfficeAssignment with "Room 101"
    Assert.NotNull(context.OfficeAssignments.Find(smith.ID));

    // Manually set the OfficeAssignment location to empty to simulate what
    // TryUpdateModelAsync would do when user clears the location field
    var instructor = context.Instructors
        .Include(i => i.OfficeAssignment)
        .Include(i => i.CourseAssignments).ThenInclude(c => c.Course)
        .Single(i => i.ID == smith.ID);
    instructor.OfficeAssignment.Location = "";
    context.SaveChanges();

    var controller = new InstructorsController(context);
    controller.ControllerContext = new Microsoft.AspNetCore.Mvc.ControllerContext
    {
        HttpContext = new Microsoft.AspNetCore.Http.DefaultHttpContext()
    };
    var services = new Microsoft.Extensions.DependencyInjection.ServiceCollection();
    services.AddLogging();
    services.AddMvcCore();
    controller.ControllerContext.HttpContext.RequestServices = services.BuildServiceProvider();

    // Act
    var result = await controller.Edit(smith.ID, new[] { "1001" });

    // Assert — office assignment should be nulled out because location is empty
    Assert.IsType<RedirectToActionResult>(result);
    context.ChangeTracker.Clear();
    var updated = context.Instructors
        .Include(i => i.OfficeAssignment)
        .Single(i => i.ID == smith.ID);
    Assert.Null(updated.OfficeAssignment);
}

[Fact]
public async Task Edit_POST_KeepsOfficeAssignment_WhenLocationNotEmpty()
{
