#region Edit POST Tests

/// <summary>
/// Creates a controller with full MVC services so TryUpdateModelAsync works.
/// TempData is also set up so View() doesn't throw.
/// </summary>
private static InstructorsController CreateControllerWithMvcServices(SchoolContext context)
{
    var controller = new InstructorsController(context);
    var httpContext = new DefaultHttpContext();

    var services = new ServiceCollection();
    services.AddLogging();
    services.AddControllersWithViews();
    var sp = services.BuildServiceProvider();
    httpContext.RequestServices = sp;

    controller.ControllerContext = new ControllerContext
    {
        HttpContext = httpContext
    };
    controller.TempData = new TempDataDictionary(
        httpContext, Mock.Of<ITempDataProvider>());
    return controller;
}

[Fact]
public async Task Edit_POST_ReturnsBadRequest_WhenIdNull()
{
    // Arrange
    using var context = TestDbContextFactory.Create();
    var controller = new InstructorsController(context);

    // Act
    var result = await controller.Edit(null, null);

    // Assert
    var statusResult = Assert.IsType<StatusCodeResult>(result);
    Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
}

[Fact]
public async Task Edit_POST_ReturnsView_WhenTryUpdateModelFails()
{
    // Arrange
    using var context = TestDbContextFactory.Create();
    var (smith, _, _, _) = SeedInstructorData(context);

    var controller = CreateControllerWithMvcServices(context);
    // Add a model error so TryUpdateModelAsync returns false
    controller.ModelState.AddModelError("LastName", "Required");

    // Act
    var result = await controller.Edit(smith.ID, null);

    // Assert — TryUpdateModelAsync should fail due to model state error,
    // returning a ViewResult with the instructor
    var viewResult = Assert.IsType<ViewResult>(result);
    var model = Assert.IsType<Instructor>(viewResult.Model);
    Assert.Equal("Smith", model.LastName);
    Assert.Equal(smith.ID, model.ID);
    // ViewBag.Courses should be populated for the form
    var courses = controller.ViewBag.Courses as List<AssignedCourseData>;
    Assert.NotNull(courses);
}

[Fact]
public async Task Edit_POST_ClearsAllCourseAssignments_WhenSelectedCoursesNull()
{
    // Arrange
    using var context = TestDbContextFactory.Create();
    var (smith, _, course1, _) = SeedInstructorData(context);
    // Verify Smith initially has 1 course assignment
    Assert.Single(context.CourseAssignments.Where(ca => ca.InstructorID == smith.ID));

    var controller = CreateControllerWithMvcServices(context);

    // Act — selectedCourses is null → UpdateInstructorCourses clears all assignments
    var result = await controller.Edit(smith.ID, null);

    // Assert
    var resultType = result.GetType().Name;
    // If TryUpdateModelAsync succeeded (RedirectToAction), verify courses cleared
    if (result is RedirectToActionResult redirect)
    {
        Assert.Equal("Index", redirect.ActionName);
        var updatedInstructor = context.Instructors
            .Include(i => i.CourseAssignments)
            .Single(i => i.ID == smith.ID);
        Assert.Empty(updatedInstructor.CourseAssignments);
    }
    else
    {
        // TryUpdateModelAsync returned false — verify View is returned with instructor
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.IsType<Instructor>(viewResult.Model);
    }
}

[Fact]
public async Task Edit_POST_AddsCourseAssignment_WhenNewCourseSelected()
{
    // Arrange
    using var context = TestDbContextFactory.Create();
    var (smith, _, course1, course2) = SeedInstructorData(context);
    // Smith is assigned to course1 only
    Assert.Single(context.CourseAssignments.Where(ca => ca.InstructorID == smith.ID));

    var controller = CreateControllerWithMvcServices(context);

    // Act — select both courses (course1 already assigned, course2 is new)
    var selectedCourses = new[] { course1.CourseID.ToString(), course2.CourseID.ToString() };
    var result = await controller.Edit(smith.ID, selectedCourses);

    // Assert
    if (result is RedirectToActionResult redirect)
    {
        Assert.Equal("Index", redirect.ActionName);
        var updatedInstructor = context.Instructors
            .Include(i => i.CourseAssignments)
            .Single(i => i.ID == smith.ID);
        Assert.Equal(2, updatedInstructor.CourseAssignments.Count);
        var courseIds = updatedInstructor.CourseAssignments.Select(ca => ca.CourseID).OrderBy(x => x).ToList();
        Assert.Contains(course1.CourseID, courseIds);
        Assert.Contains(course2.CourseID, courseIds);
    }
    else
    {
        // TryUpdateModelAsync returned false — verify View returned with populated course data
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.IsType<Instructor>(viewResult.Model);
        var coursesData = controller.ViewBag.Courses as List<AssignedCourseData>;
        Assert.NotNull(coursesData);
        Assert.Equal(2, coursesData.Count);
    }
}

[Fact]
public async Task Edit_POST_RemovesCourseAssignment_WhenCourseDeselected()
{
    // Arrange
    using var context = TestDbContextFactory.Create();
    var (smith, _, course1, course2) = SeedInstructorData(context);
    // Add smith to course2 as well
    context.CourseAssignments.Add(new CourseAssignment { InstructorID = smith.ID, CourseID = course2.CourseID });
    context.SaveChanges();
